import numpy as np
def load(fn):
    lines = open(fn).read().split('\n')[2:]
    els, xyz = [], []
    for l in lines:
        p=l.split()
        if len(p)==4: els.append(p[0]); xyz.append([float(x) for x in p[1:]])
    return els, np.array(xyz)
e1, a = load('init3.xyz')
e2, b = load('opt3.xyz')
for tag,xyz in [('init3',a),('opt3',b)]:
    print(tag, 'Ni-H78/79/80:', [round(np.linalg.norm(xyz[h]-xyz[46]),2) for h in (78,79,80)])
# dihedral Ni..C56-C57-H80 in both
def dih(p0,p1,p2,p3):
    b0=p0-p1; b1=p2-p1; b2=p3-p2
    b1/=np.linalg.norm(b1)
    v=b0-np.dot(b0,b1)*b1; w=b2-np.dot(b2,b1)*b1
    return np.degrees(np.arctan2(np.dot(np.cross(b1,v),w), np.dot(v,w)))
for tag,xyz in [('init3',a),('opt3',b)]:
    print(tag, 'dihedral Ni-C56-C57-H80:', round(dih(xyz[46],xyz[56],xyz[57],xyz[80]),1))
